<script setup>
import { computed, onMounted, ref } from 'vue'

const props = defineProps({ permissions: { type: Array, default: () => [] }, roles: { type: Array, default: () => [] }, userId: Number })
const allowed = new Set(props.permissions)
const can = (permission) => allowed.has(permission)
const path = window.location.pathname
const section = path === '/billing' ? 'overview' : path.split('/').at(-1)
const sections = { overview: 'Billing Overview', ready: 'Ready for Billing', register: 'Invoice Register', create: 'Create Invoice', approvals: 'Invoice Approval Queue', revisions: 'Invoice Revisions', documents: 'Billing Documents', exceptions: 'Billing Exceptions' }
const pageTitle = sections[section] || 'Billing Overview'
const data = ref({ metrics: {}, ready: [], recent: [], approval_queue: [], exceptions: [], trend: [] })
const readyRows = ref([])
const invoices = ref([])
const exceptions = ref([])
const documents = ref([])
const history = ref([])
const selectedShipment = ref(null)
const chargeRows = ref([])
const eligibility = ref(null)
const selectedSources = ref([])
const selectedInvoice = ref(null)
const search = ref('')
const status = ref('')
const busy = ref(false)
const loading = ref(true)
const error = ref('')
const notice = ref('')
const reviewComment = ref('')
const dueDate = ref('')
const remarks = ref('')
const showCreate = ref(section === 'create')
const reviewOpen = ref(false)
const reviewAction = ref('approve')
const selectedFile = ref(null)
const money = (value, currency = 'PHP') => value == null ? 'Unavailable' : new Intl.NumberFormat(undefined, { style: 'currency', currency, minimumFractionDigits: 2 }).format(Number(value))
const currencyLabel = (value) => value || 'â€”'
const rows = computed(() => section === 'ready' ? readyRows.value : section === 'approvals' ? data.value.approval_queue || [] : invoices.value)
const invoicedThisMonth = computed(() => (data.value.metrics.issued_this_month_by_currency || []).map(item => money(item.amount, item.currency)).join(' Â· ') || 'No invoices issued this month')
const outstandingReceivables = computed(() => (data.value.metrics.outstanding_balance || []).map(item => money(item.amount, item.currency)).join(' Â· ') || 'No open invoices')

const trendPercent = (item) => { const values = (data.value.trend || []).filter(row => row.currency === item.currency).map(row => Number(row.amount) || 0); return Math.min(100, Math.max(3, (Number(item.amount) || 0) / Math.max(1, ...values) * 100)) }
const statusPercent = (item) => { const values = (data.value.status_distribution || []).map(row => Number(row.count) || 0); return Math.max(3, (Number(item.count) || 0) / Math.max(1, ...values) * 100) }

async function api(url, options = {}) {
  const response = await fetch(url, { credentials: 'same-origin', ...options, headers: { Accept: 'application/json', ...(options.body ? { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]')?.content || '' } : {}), ...(options.headers || {}) } })
  const body = await response.json().catch(() => ({}))
  if (!response.ok) {
    if (response.status === 401) throw new Error('Your IFC sign-in session has expired. Sign in again to continue.')
    if (response.status === 403) throw new Error('Your account does not have permission to perform this action.')
    const validation = body.errors ? Object.values(body.errors).flat().join(' ') : ''
    throw new Error(validation || body.message || 'Billing request failed. Please retry.')
  }
  return body
}

async function load() {
  loading.value = true; error.value = ''
  try {
    if (section === 'overview') data.value = (await api('/api/billing/dashboard')).data
    if (section === 'ready' || section === 'create') readyRows.value = (await api('/api/billing/ready')).data.data || []
    if (['register', 'approvals', 'revisions', 'documents'].includes(section)) invoices.value = (await api(`/api/billing/invoices?search=${encodeURIComponent(search.value)}&status=${encodeURIComponent(status.value)}`)).data.data || []
    if (section === 'exceptions') exceptions.value = (await api('/api/billing/exceptions')).data.data || []
  } catch (e) { error.value = e.message } finally { loading.value = false }
}

async function openCreate(shipment) {
  selectedShipment.value = shipment; selectedSources.value = []; chargeRows.value = []; eligibility.value = null; error.value = ''; notice.value = ''
  showCreate.value = true
  try {
    const result = await api(`/api/billing/shipments/${shipment.shipment_id}/charges`)
    chargeRows.value = result.data || []; eligibility.value = result.eligibility
    selectedSources.value = chargeRows.value.map(row => row.source_key)
  } catch (e) { error.value = e.message }
}

async function createDraft() {
  if (!selectedShipment.value || !selectedSources.value.length) return
  busy.value = true; error.value = ''; notice.value = ''
  try {
    const result = await api('/api/billing/invoices', { method: 'POST', body: JSON.stringify({ shipment_id: selectedShipment.value.shipment_id, source_keys: selectedSources.value, idempotency_key: crypto.randomUUID(), due_date: dueDate.value || null, remarks: remarks.value || null }) })
    selectedInvoice.value = result.data; notice.value = `${result.data.reference} saved as a draft.`; showCreate.value = false
    await load()
  } catch (e) { error.value = e.message } finally { busy.value = false }
}

async function submitInvoice(invoice) {
  if (!window.confirm(`Submit ${invoice.reference} for Accounting review?`)) return
  await act(`/api/billing/invoices/${invoice.id}/submit`, 'POST', {})
}

async function cancelDraft(invoice) {
  const reason = window.prompt(`Why is ${invoice.reference} being canceled?`)
  if (!reason?.trim()) return
  await act(`/api/billing/invoices/${invoice.id}/cancel-draft`, 'POST', { reason })
}

async function saveReview() {
  if (!selectedInvoice.value) return
  await act(`/api/billing/invoices/${selectedInvoice.value.id}/review`, 'POST', { action: reviewAction.value, comments: reviewComment.value })
  reviewOpen.value = false
}

async function act(url, method, payload) {
  busy.value = true; error.value = ''; notice.value = ''
  try { const result = await api(url, { method, body: JSON.stringify(payload) }); notice.value = result.message || 'Billing record updated.'; await load() } catch (e) { error.value = e.message } finally { busy.value = false }
}

async function openInvoice(invoice) {
  try {
    selectedInvoice.value = (await api(`/api/billing/invoices/${invoice.id}`)).data
    documents.value = []; history.value = []
    if (can('billing.invoices.create') || can('billing.invoices.review') || can('billing.invoices.download')) documents.value = (await api(`/api/billing/invoices/${invoice.id}/documents`)).data || []
  } catch (e) { error.value = e.message }
}

function preview(invoice) { window.open(`/api/billing/invoices/${invoice.id}/preview`, '_blank', 'noopener') }
function review(invoice, action = 'approve') { selectedInvoice.value = invoice; reviewAction.value = action; reviewComment.value = ''; reviewOpen.value = true }
function statusLabel(value) { return (value || 'unknown').replaceAll('_', ' ') }

async function viewHistory(invoice) {
  try { history.value = (await api(`/api/billing/invoices/${invoice.id}/history`)).data.events || [] } catch (e) { error.value = e.message }
}

async function uploadDocument() {
  if (!selectedFile.value || !selectedInvoice.value) return
  busy.value = true; error.value = ''
  try {
    const form = new FormData(); form.append('document', selectedFile.value)
    const response = await fetch(`/api/billing/invoices/${selectedInvoice.value.id}/documents`, { method: 'POST', credentials: 'same-origin', headers: { Accept: 'application/json', 'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]')?.content || '' }, body: form })
    const body = await response.json().catch(() => ({}))
    if (!response.ok) throw new Error(body.message || (response.status === 403 ? 'You cannot upload documents for this invoice.' : 'Document upload failed.'))
    selectedFile.value = null; documents.value = (await api(`/api/billing/invoices/${selectedInvoice.value.id}/documents`)).data || []; notice.value = body.message
  } catch (e) { error.value = e.message } finally { busy.value = false }
}

async function resolveException(item) {
  const resolution = window.prompt('Resolution details')
  if (!resolution?.trim()) return
  await act(`/api/billing/exceptions/${item.id}/resolve`, 'POST', { resolution })
}

onMounted(load)
</script>

<template>
  <div class="billing-workspace">
    <header class="billing-heading"><div><span class="billing-kicker">INTERFREIGHT GROUP / FINANCIAL OPERATIONS</span><h1>{{ pageTitle }}</h1><p>Invoice only from accepted commercial terms and verified client-authorized changes.</p></div><div class="billing-heading-actions"><a v-if="can('billing.ready.view')" href="/billing/ready" class="bill-secondary">Ready queue</a><a v-if="can('billing.invoices.create')" href="/billing/create" class="bill-primary">Create Invoice</a></div></header>
    <nav class="billing-tabs" aria-label="Billing navigation"><a v-for="item in Object.entries(sections).filter(([key]) => key !== 'create' || can('billing.invoices.create')).filter(([key]) => key === 'overview' ? can('billing.dashboard.view') : key === 'ready' ? can('billing.ready.view') : key === 'approvals' ? can('billing.invoices.review') : key === 'exceptions' ? can('billing.exceptions.view') : ['register','revisions','documents'].includes(key) ? can('billing.invoices.view') : true)" :key="item[0]" :href="item[0] === 'overview' ? '/billing' : `/billing/${item[0]}`" :class="{ active: section === item[0] }">{{ item[1] }}</a></nav>
    <div v-if="notice" class="billing-success" role="status">{{ notice }}</div><div v-if="error" class="billing-alert" role="alert">{{ error }} <a href="/login">Sign in again</a></div>

    <template v-if="section === 'overview'">
      <section class="billing-kpis" aria-label="Billing metrics"><article><small>Ready for Billing</small><b>{{ data.metrics.ready ?? 'â€”' }}</b><span>Accepted commercial authorization</span></article><article><small>Draft Invoices</small><b>{{ data.metrics.drafts ?? 'â€”' }}</b><span>Not issued</span></article><article><small>Pending Approval</small><b>{{ data.metrics.pending_approval ?? 'â€”' }}</b><span>Accounting review</span></article><article><small>Awaiting Issuance</small><b>{{ data.metrics.awaiting_issuance ?? 'â€”' }}</b><span>Legal configuration required</span></article><article><small>Issued Invoices</small><b>{{ data.metrics.issued ?? 'â€”' }}</b><span>See reconciled balances</span></article><article><small>Invoiced This Month</small><b class="billing-small-value">{{ invoicedThisMonth }}</b><span>Grouped by currency</span></article><article><small>Outstanding Balance</small><b class="billing-small-value">{{ data.metrics.collection_status === 'permission_required' ? 'Restricted' : outstandingReceivables }}</b><span>Reconciled balances by currency � <a v-if="can('collections.view')" href="/collections">View receivables</a><span v-else>Collection access restricted</span></span></article><article><small>Overdue Invoices</small><b>{{ data.metrics.overdue ?? 'Restricted' }}</b><span>Open issued invoices past due � <a v-if="can('collections.view')" href="/collections">Review aging</a><span v-else>Collection access restricted</span></span></article><article><small>Open Exceptions</small><b>{{ data.metrics.exceptions ?? 'â€”' }}</b><span>Requires resolution</span></article></section>
      <section class="billing-panel"><header><div><h2>Ready for Billing Queue</h2><p>Draft eligibility is based on the accepted commercial baseline.</p></div><a href="/billing/ready">Open queue â†’</a></header><div class="billing-table-wrap"><table><thead><tr><th>Shipment</th><th>Client</th><th>Accepted Quotation</th><th>Service</th><th>Currency</th><th>Eligibility</th><th></th></tr></thead><tbody><tr v-for="row in data.ready" :key="row.shipment_id"><td><b>{{ row.job_number || row.shipment_reference }}</b></td><td>{{ row.company_name }}</td><td>{{ row.quotation_reference }}<small>Baseline v{{ row.quotation_version }}</small></td><td>{{ row.service_type || row.mode || 'â€”' }}</td><td>{{ row.currency }}</td><td><span class="billing-badge ready">Draft eligible</span></td><td><button v-if="can('billing.invoices.create')" class="bill-link" @click="openCreate(row)">Create draft</button></td></tr><tr v-if="!data.ready?.length"><td colspan="7" class="billing-empty">{{ loading ? 'Loading queueâ€¦' : 'No shipments currently meet the billing baseline checks.' }}</td></tr></tbody></table></div></section>
      <div class="billing-lower"><section class="billing-panel"><header><div><h2>Recent Invoices</h2><p>Current workflow states</p></div><a href="/billing/register">Invoice register â†’</a></header><div class="billing-list"><button v-for="item in data.recent" :key="item.id" @click="openInvoice(item)"><span><b>{{ item.reference }}</b><small>{{ item.company_name }} Â· {{ item.job_number }}</small></span><span class="billing-badge" :class="item.workflow_status">{{ statusLabel(item.workflow_status) }}</span><strong>{{ item.total ? money(item.total, item.currency) : 'Tax review required' }}</strong></button><p v-if="!data.recent?.length" class="billing-empty">{{ loading ? 'Loading invoicesâ€¦' : 'No invoices have been prepared.' }}</p></div></section><section class="billing-panel"><header><div><h2>Issuance and Collections</h2><p>Workflow readiness</p></div></header><div class="billing-readiness"><p><b>Official invoice issuance</b><span>Blocked until company tax details and statutory numbering are verified.</span></p><p><b>Customer payments</b><span>Accounting records receipts; Finance independently reconciles them against evidence.</span></p><p><b>Collection monitoring</b><span>Review issued invoice balances, due dates, aging and payment history.</span></p><a href="/collections" class="bill-link">Open collection monitoring â†’</a><p><b>Accounting posting</b><span>External accounting ledger posting is not connected.</span></p></div></section></div>
      <div class="billing-analytics"><section class="billing-panel"><header><div><h2>Monthly Invoicing Trend</h2><p>Issued amounts are separated by currency.</p></div></header><div class="billing-chart-list"><div v-for="item in data.trend" :key="item.month + item.currency"><span>{{ item.month }}</span><i><b :style="{ width: trendPercent(item) + '%' }"></b></i><strong>{{ money(item.amount, item.currency) }}</strong></div><p v-if="!data.trend?.length">{{ loading ? 'Loading trendâ€¦' : 'No issued invoices to chart.' }}</p></div></section><section class="billing-panel"><header><div><h2>Workflow Distribution</h2><p>All invoice workflow states</p></div></header><div class="billing-chart-list"><div v-for="item in data.status_distribution" :key="item.workflow_status"><span>{{ statusLabel(item.workflow_status) }}</span><i><b :style="{ width: statusPercent(item) + '%' }"></b></i><strong>{{ item.count }}</strong></div><p v-if="!data.status_distribution?.length">{{ loading ? 'Loading statesâ€¦' : 'No invoice activity yet.' }}</p></div><div class="billing-readiness"><p><b>Aging / receivables</b><span>Open balances are grouped by due date in collection monitoring.</span></p><a v-if="can('collections.view')" href="/collections" class="bill-link">Review receivables aging â†’</a></div></section><section class="billing-panel"><header><div><h2>Issued Amount by Client</h2><p>Separated by currency</p></div></header><div class="billing-chart-list"><div v-for="item in data.by_client" :key="item.company_name + item.currency"><span>{{ item.company_name }}</span><strong>{{ money(item.amount,item.currency) }}</strong></div><p v-if="!data.by_client?.length">No issued invoices to report.</p></div></section><section class="billing-panel"><header><div><h2>Issued Amount by Service</h2><p>Separated by currency</p></div></header><div class="billing-chart-list"><div v-for="item in data.by_service" :key="item.service_type + item.currency"><span>{{ item.service_type || 'Unspecified' }}</span><strong>{{ money(item.amount,item.currency) }}</strong></div><p v-if="!data.by_service?.length">No issued invoices to report.</p></div></section></div>
    </template>

    <template v-else-if="section === 'ready' || section === 'create' || section === 'approvals' || section === 'register' || section === 'revisions' || section === 'documents'">
      <section class="billing-panel"><header><div><h2>{{ section === 'ready' || section === 'create' ? 'Shipment eligibility' : section === 'approvals' ? 'Invoices requiring Accounting review' : 'Central invoice register' }}</h2><p>{{ section === 'ready' || section === 'create' ? 'Only accepted quotation baseline lines and verified client approvals can be selected.' : 'Search by internal reference, client, or shipment. Collection details are available in Collection Monitoring.' }}</p></div><span>{{ rows.length }} records</span></header><div v-if="section !== 'ready' && section !== 'create' && section !== 'approvals'" class="billing-toolbar"><input v-model="search" placeholder="Search invoice, client, shipment" @input="load"><select v-model="status" @change="load"><option value="">All workflow states</option><option v-for="s in ['draft','submitted','approved','rejected','revision_requested','issued']" :key="s" :value="s">{{ statusLabel(s) }}</option></select></div><div class="billing-table-wrap"><table><thead><tr><th>Reference</th><th>Client / Shipment</th><th>Dates</th><th>Currency</th><th>Total</th><th>Approval / Issue</th><th>Payment</th><th>Actions</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><b>{{ row.reference || row.job_number }}</b><small v-if="row.official_number">Official {{ row.official_number }}</small><small v-else-if="row.quotation_reference">{{ row.quotation_reference }}</small></td><td>{{ row.company_name }}<small>{{ row.job_number || row.shipment_reference }}</small></td><td>{{ row.invoice_date || 'Draft' }}<small>Due {{ row.due_date || 'Not set' }}</small></td><td>{{ row.currency }}</td><td>{{ row.total ? money(row.total,row.currency) : can('billing.invoices.create') ? 'Tax classification required' : 'Status only' }}</td><td><span class="billing-badge" :class="row.workflow_status">{{ statusLabel(row.workflow_status || 'ready') }}</span></td><td><a href="/collections">View collections</a></td><td class="billing-actions"><button class="bill-link" @click="row.id ? openInvoice(row) : openCreate(row)">{{ row.id ? 'View' : 'Prepare' }}</button><button v-if="row.workflow_status === 'draft' && can('billing.invoices.submit')" class="bill-link" @click="submitInvoice(row)">Submit</button><button v-if="row.workflow_status === 'submitted' && can('billing.invoices.review')" class="bill-link" @click="review(row)">Review</button><button v-if="row.id && can('billing.invoices.download')" class="bill-link" @click="preview(row)">Preview</button></td></tr><tr v-if="!rows.length"><td colspan="8" class="billing-empty">{{ loading ? 'Loading billing recordsâ€¦' : 'No records match this view.' }}</td></tr></tbody></table></div></section>
      <div class="billing-notice">Draft previews are non-statutory. Official issuance is disabled until verified company tax configuration and compliant numbering are provided.</div>
    </template>

    <template v-else-if="section === 'exceptions'"><section class="billing-panel"><header><div><h2>Billing Exceptions</h2><p>Exceptions are retained after resolution for audit history.</p></div><span>{{ exceptions.length }} records</span></header><div class="billing-table-wrap"><table><thead><tr><th>Type</th><th>Severity</th><th>Related record</th><th>Explanation</th><th>Status</th><th>Resolution</th><th></th></tr></thead><tbody><tr v-for="item in exceptions" :key="item.id"><td>{{ statusLabel(item.exception_type) }}</td><td>{{ item.severity }}</td><td>{{ item.invoice_id ? `Invoice #${item.invoice_id}` : item.shipment_id ? `Shipment #${item.shipment_id}` : 'â€”' }}</td><td>{{ item.explanation }}</td><td>{{ item.status }}</td><td>{{ item.resolution || 'â€”' }}</td><td><button v-if="item.status === 'open' && can('billing.exceptions.resolve')" class="bill-link" @click="resolveException(item)">Resolve</button></td></tr><tr v-if="!exceptions.length"><td colspan="7" class="billing-empty">{{ loading ? 'Loading exceptionsâ€¦' : 'No billing exceptions are open.' }}</td></tr></tbody></table></div></section></template>

    <div v-if="showCreate" class="billing-overlay" @click.self="showCreate = false"><section class="billing-modal" role="dialog" aria-modal="true" aria-labelledby="billing-create-title"><header><div><span>AUTHORIZED COMMERCIAL SCOPE</span><h2 id="billing-create-title">Create invoice draft</h2><p>{{ selectedShipment?.job_number || selectedShipment?.shipment_reference || 'Choose a shipment below.' }}</p></div><button class="bill-close" aria-label="Close dialog" @click="showCreate = false">Ã—</button></header><template v-if="!selectedShipment"><p>Select a ready shipment from the queue.</p><button v-for="row in readyRows" :key="row.shipment_id" class="billing-choice" @click="openCreate(row)">{{ row.job_number || row.shipment_reference }} Â· {{ row.company_name }}</button></template><template v-else><div v-if="eligibility" class="billing-info"><b>{{ eligibility.message }}</b><span>{{ eligibility.milestone_policy }}</span></div><fieldset class="billing-charge-list"><legend>Authorized charges</legend><label v-for="charge in chargeRows" :key="charge.source_key"><input v-model="selectedSources" type="checkbox" :value="charge.source_key"><span><b>{{ charge.description }}</b><small>{{ charge.authorization_reference }} Â· {{ charge.quantity }} {{ charge.unit }}</small></span><strong>{{ money(charge.remaining_amount, charge.currency) }}</strong><em v-if="charge.tax_treatment === null">Tax unconfigured</em></label><p v-if="!chargeRows.length">No unbilled authorized charges were found.</p></fieldset><div class="billing-form-grid"><label>Invoice date<input :value="new Date().toISOString().slice(0,10)" disabled><small>Set on submission using application date.</small></label><label>Due date<input v-model="dueDate" type="date"></label><label class="full">Payment terms<input :value="selectedShipment.payment_terms || 'As stated in accepted quotation'" disabled></label><label class="full">Billing remarks<textarea v-model="remarks" maxlength="2000" rows="3"></textarea></label></div><div class="billing-info warn">Totals are calculated from stored authorized lines. Tax treatment for additional charges is not configured, and this draft cannot be issued as a legal invoice.</div></template><footer><button class="bill-secondary" @click="showCreate = false">Cancel</button><button v-if="selectedShipment" class="bill-primary" :disabled="busy || !selectedSources.length" @click="createDraft">{{ busy ? 'Savingâ€¦' : 'Save Draft' }}</button></footer></section></div>

    <div v-if="selectedInvoice && !reviewOpen" class="billing-overlay" @click.self="selectedInvoice = null"><section class="billing-modal" role="dialog" aria-modal="true"><header><div><span>INVOICE WORKFLOW</span><h2>{{ selectedInvoice.reference }}</h2><p>{{ selectedInvoice.company_name }} Â· {{ selectedInvoice.job_number }} Â· {{ statusLabel(selectedInvoice.workflow_status) }}</p></div><button class="bill-close" aria-label="Close dialog" @click="selectedInvoice = null">Ã—</button></header><div v-if="can('billing.invoices.create') || can('billing.invoices.review')" class="billing-detail-grid"><div><small>Invoice total</small><b>{{ selectedInvoice.total ? money(selectedInvoice.total, selectedInvoice.currency) : 'Tax configuration required' }}</b></div><div><small>Payment status</small><b>{{ selectedInvoice.collection_status === 'restricted' ? 'Restricted' : selectedInvoice.collection_status === 'not_issued' ? 'Not issued' : money(selectedInvoice.collection_outstanding, selectedInvoice.currency) + ' outstanding � ' + money(selectedInvoice.collection_paid, selectedInvoice.currency) + ' collected' }}</b></div><div><small>Due date</small><b>{{ selectedInvoice.due_date || 'Not set' }}</b></div><div><small>Accounting handover</small><b>{{ statusLabel(selectedInvoice.accounting_handover) }}</b></div></div><p v-else>Invoice and collection details are restricted to authorized financial roles.</p><div v-if="can('billing.invoices.create') || can('billing.invoices.review')" class="billing-table-wrap"><table><thead><tr><th>Charge</th><th>Authorization</th><th>Amount</th><th>Currency</th></tr></thead><tbody><tr v-for="line in selectedInvoice.lines" :key="line.id"><td>{{ line.description }}</td><td>{{ line.authorization_reference }}</td><td>{{ money(line.line_amount,line.currency) }}</td><td>{{ line.currency }}</td></tr></tbody></table></div><div v-if="selectedInvoice.approvals?.length" class="billing-history"><b>Review history</b><p v-for="entry in selectedInvoice.approvals" :key=